// Each item here is one alert object from Kibana's webhook action payload
// (context.alerts[N] from the .webhook connector, body = {{{context}}}).
// Unlike the polling pipeline's raw ES search hits, these arrive without a
// _source wrapper -- fields like host/process/kibana.alert.rule.* are
// already at the top level.
const alert = $json;
const alertId = alert._id;

const ruleName = (alert.kibana && alert.kibana.alert && alert.kibana.alert.rule && alert.kibana.alert.rule.name)
  || (alert.signal && alert.signal.rule && alert.signal.rule.name)
  || 'Unknown rule';

const host = (alert.host && alert.host.name) || 'unknown-host';

const description = (alert.kibana && alert.kibana.alert && alert.kibana.alert.rule && alert.kibana.alert.rule.description)
  || (alert.signal && alert.signal.rule && alert.signal.rule.description)
  || '';

const raw = JSON.stringify(alert).slice(0, 3000);

const prompt = [
  'You are a SOC triage analyst. Read the detection alert below and respond',
  'with ONLY a single JSON object, no other text, matching this schema:',
  '{"severity": "low|medium|high|critical", "false_positive_likelihood": "low|medium|high", "summary": "one sentence", "recommended_action": "one sentence"}',
  '',
  'Alert:',
  'Rule: ' + ruleName,
  'Host: ' + host,
  'Description: ' + description,
  'Raw fields (truncated): ' + raw
].join('\n');

return {
  json: {
    prompt,
    alert_id: alertId,
    original_alert: alert
  }
};

const llmOutput = $json;
const original = $('Build Prompt').item.json.original_alert;
const alertId = $('Build Prompt').item.json.alert_id;

let triage;
try {
  triage = JSON.parse(llmOutput.response);
} catch (e) {
  triage = {
    severity: 'unknown',
    false_positive_likelihood: 'unknown',
    summary: 'LLM output could not be parsed as JSON',
    recommended_action: 'manual review',
    raw_llm_output: llmOutput.response
  };
}

// Real per-event MTTD, for dashboard trending -- not the one-off
// validation.yml measurements. Kibana's {{{context}}} rendering nests
// kibana.alert.*, unlike a raw ES search hit's flat-dotted key, but check
// both shapes defensively.
const alertStartRaw = (original.kibana && original.kibana.alert && original.kibana.alert.start)
  || original['kibana.alert.start'];
const mttdSeconds = alertStartRaw ? Math.round((Date.now() - new Date(alertStartRaw).getTime()) / 1000) : null;

// Own doc id (alertId + '-push'), distinct from the polling pipeline's plain
// alertId -- both pipelines are active in parallel for comparison, and without
// this they'd silently overwrite each other's triage result via the shared
// PUT-by-id idempotency pattern.
const doc = {
  '@timestamp': new Date().toISOString(),
  alert_id: alertId,
  alert: original,
  triage,
  triage_source: 'push',
  mttd_seconds: mttdSeconds
};

const auth = 'Basic ' + Buffer.from('elastic:' + $env.N8N_ELASTIC_PASSWORD).toString('base64');

return { json: { doc, auth, docId: alertId + '-push' } };

// Automated response is deliberately narrow: only high/critical severity
// AND low false-positive likelihood, AND only a bounded, reversible action
// (kill one process by pid -- see infra/compose/wazuh/responder/responder.py,
// which also independently refuses to touch protected system processes
// regardless of what gets sent here). Items that don't qualify are dropped
// -- this node's output IS the response-triggered subset, not a pass/fail
// flag for a downstream branch.
const results = [];
for (const item of $input.all()) {
  const doc = item.json.doc;
  const triage = doc.triage || {};
  const alert = doc.alert || {};

  const severity = (triage.severity || '').toLowerCase();
  const fpLikelihood = (triage.false_positive_likelihood || '').toLowerCase();
  const pid = alert.process && alert.process.pid;

  const eligible = ['high', 'critical'].includes(severity)
    && fpLikelihood === 'low'
    && typeof pid === 'number'
    && pid > 1;

  if (!eligible) continue;

  const ruleName = (alert.kibana && alert.kibana.alert && alert.kibana.alert.rule && alert.kibana.alert.rule.name) || 'Unknown rule';
  const hostName = (alert.host && alert.host.name) || 'unknown-host';

  results.push({
    json: {
      pid,
      reason: `Automated response: ${severity} severity, ${fpLikelihood} FP likelihood - ${ruleName} on ${hostName}`,
      alert_id: doc.alert_id
    }
  });
}
return results;
